/** Renders a list of line items as a receipt with a total (see SPEC.md). */
export function formatReceipt(lines: Array<{ label: string; cents: number }>): string {
	const itemLines = lines.map((line) => `${line.label}: ${formatCents(line.cents)}`);
	const total = lines.reduce((sum, line) => sum + line.cents, 0);
	itemLines.push(`Total: ${formatCents(total)}`);
	return itemLines.join('\n');
}
```

It builds one `<label>: <formatCents(cents)>` line per item (calling the existing `formatCents`, per spec), appends a `Total: <formatCents(sum)>` line, and joins everything with `\n`. For an empty `lines` array, it produces just the `Total:` line, as required.

